import type { Feature, FeatureCollection, Geometry } from "geojson";

/** [longitude, latitude] — matches MapLibre's LngLat exactly. */
export type Coordinate = [longitude: number, latitude: number];

/** [west, south, east, north]. */
export type Bounds = [west: number, south: number, east: number, north: number];

export type MapRenderer = "maplibre" | "mapbox";

export interface MapViewport {
  center: Coordinate;
  zoom: number;
  bearing: number;
  pitch: number;
}

export type PartialViewport = Partial<MapViewport>;

export interface EdgePadding {
  top?: number;
  right?: number;
  bottom?: number;
  left?: number;
}

export interface MapCameraAnimation {
  /** ms. 0 = instant. */
  duration?: number;
  easing?: "linear" | "ease" | "fly";
  padding?: EdgePadding;
}

export interface ScreenPoint {
  x: number;
  y: number;
}

export interface MapFeaturePressEvent {
  coordinate: Coordinate;
  point: ScreenPoint;
  features: Array<Feature>;
}

export type GeoJSONInput = Feature | FeatureCollection | Geometry | string;

/**
 * A style-spec expression: `["get", "color"]`, `["interpolate", ...]`, etc.
 * Kept loose on purpose — both renderers share the same expression grammar
 * (see plan §1.2), so we don't attempt to model it more strictly than the
 * upstream style specs already do.
 */

export type Expression = Array<any>;

export type StyleValue<T> = T | Expression;

/** Shared style objects — identical key names on both renderers. */
export interface PointStyle {
  color?: StyleValue<string>;
  radius?: StyleValue<number>;
  opacity?: StyleValue<number>;
  strokeColor?: StyleValue<string>;
  strokeWidth?: StyleValue<number>;
}

export interface LineStyle {
  color?: StyleValue<string>;
  width?: StyleValue<number>;
  opacity?: StyleValue<number>;
  dashArray?: Array<number>;
  cap?: "butt" | "round" | "square";
  join?: "bevel" | "round" | "miter";
}

export interface FillStyle {
  color?: StyleValue<string>;
  opacity?: StyleValue<number>;
  outlineColor?: StyleValue<string>;
}

export interface TextStyle {
  color?: StyleValue<string>;
  size?: StyleValue<number>;
  haloColor?: string;
  haloWidth?: number;
  font?: Array<string>;
}

export type ColorScheme = "light" | "dark";

export type OrnamentPosition = "top-left" | "top-right" | "bottom-left" | "bottom-right";

/** Plain data driving <MapLegend> — deliberately decoupled from any rendering component. */
export type MapLegendData =
  | { type: "categorical"; items: Array<{ label: string; color: string; value?: string | number }> }
  | { type: "steps"; items: Array<{ label: string; color: string; from?: number; to?: number }>; unit?: string }
  | { type: "gradient"; stops: Array<{ at: number; color: string }>; domain: [number, number]; unit?: string };

import type { Feature, FeatureCollection, Geometry, GeoJsonProperties, Polygon } from "geojson";
import type { Bounds, Coordinate, GeoJSONInput, MapViewport, PartialViewport } from "./types";

/** Mean Earth radius in meters (same constant Turf.js uses). */
const EARTH_RADIUS_METERS = 6_371_008.8;

export type DistanceUnit = "meters" | "kilometers" | "miles" | "feet";

const UNIT_TO_METERS: Record<DistanceUnit, number> = {
  meters: 1,
  kilometers: 1000,
  miles: 1609.344,
  feet: 0.3048,
};

export function toMeters(distance: number, unit: DistanceUnit = "meters"): number {
  return distance * UNIT_TO_METERS[unit];
}

function toRadians(degrees: number): number {
  return (degrees * Math.PI) / 180;
}

function toDegrees(radians: number): number {
  return (radians * 180) / Math.PI;
}

/**
 * Great-circle destination point given a start coordinate, a bearing (degrees
 * clockwise from north) and a distance in meters.
 */
export function destinationPoint(
  origin: Coordinate,
  distanceMeters: number,
  bearingDegrees: number,
): Coordinate {
  const [lon, lat] = origin;
  const delta = distanceMeters / EARTH_RADIUS_METERS;
  const bearing = toRadians(bearingDegrees);
  const lat1 = toRadians(lat);
  const lon1 = toRadians(lon);

  const lat2 = Math.asin(
    Math.sin(lat1) * Math.cos(delta) + Math.cos(lat1) * Math.sin(delta) * Math.cos(bearing),
  );
  const lon2 =
    lon1 +
    Math.atan2(
      Math.sin(bearing) * Math.sin(delta) * Math.cos(lat1),
      Math.cos(delta) - Math.sin(lat1) * Math.sin(lat2),
    );

  // Normalize longitude to [-180, 180] so circles crossing the antimeridian
  // don't produce out-of-range coordinates.
  const normalizedLon = (((toDegrees(lon2) + 540) % 360) - 180);

  return [normalizedLon, toDegrees(lat2)];
}

/** Great-circle distance between two coordinates, in meters. */
export function distance(a: Coordinate, b: Coordinate): number {
  const [lon1, lat1] = a;
  const [lon2, lat2] = b;
  const dLat = toRadians(lat2 - lat1);
  const dLon = toRadians(lon2 - lon1);
  const rLat1 = toRadians(lat1);
  const rLat2 = toRadians(lat2);

  const sinDLat = Math.sin(dLat / 2);
  const sinDLon = Math.sin(dLon / 2);
  const h = sinDLat * sinDLat + Math.cos(rLat1) * Math.cos(rLat2) * sinDLon * sinDLon;

  return 2 * EARTH_RADIUS_METERS * Math.asin(Math.min(1, Math.sqrt(h)));
}

export function coordinateEquals(a: Coordinate, b: Coordinate, epsilon = 1e-9): boolean {
  return Math.abs(a[0] - b[0]) < epsilon && Math.abs(a[1] - b[1]) < epsilon;
}

const COORDINATE_EPSILON = 1e-7;
const DEGREE_EPSILON = 1e-3;

/**
 * Compares a full viewport against a (possibly partial) one within the
 * tolerances `Map` uses to suppress camera echo -- see plan §7.1 ("loop
 * prevention"). Fields absent from `partial` are treated as equal (a
 * `{ zoom: 12 }` update should not be considered "different" just because
 * `center` wasn't specified).
 */
export function viewportEquals(a: MapViewport, partial: PartialViewport, epsilon = COORDINATE_EPSILON): boolean {
  if (partial.center && !coordinateEquals(a.center, partial.center, epsilon)) return false;
  if (partial.zoom !== undefined && Math.abs(a.zoom - partial.zoom) >= DEGREE_EPSILON) return false;
  if (partial.bearing !== undefined && Math.abs(a.bearing - partial.bearing) >= DEGREE_EPSILON) return false;
  if (partial.pitch !== undefined && Math.abs(a.pitch - partial.pitch) >= DEGREE_EPSILON) return false;
  return true;
}

/**
 * Picks a polygon resolution that stays visually smooth regardless of
 * radius: small circles don't need many points, very large ones need more
 * to avoid faceting at high zoom.
 */
export function stepsForRadius(radiusMeters: number, requested?: number): number {
  if (requested !== undefined) return requested;
  if (radiusMeters > 100_000) return 128;
  return 64;
}

/**
 * Generates a real-world-accurate circle polygon around `center`. Uses the
 * great-circle destination formula rather than a native `circle` layer
 * because circle-layer radii are in screen pixels and don't represent a
 * true geographic radius (see plan §7.8).
 *
 * Distortion near the poles and antimeridian-crossing circles (rendered as
 * a MultiPolygon) are inherent to any planar/Mercator rendering of a
 * geodesic circle and are documented, not "fixed", here.
 */
export function circlePolygon(
  center: Coordinate,
  radiusMeters: number,
  steps?: number,
  properties: GeoJsonProperties = {},
): Feature<Polygon> {
  const resolvedSteps = stepsForRadius(radiusMeters, steps);
  const ring: Array<Coordinate> = [];

  for (let i = 0; i < resolvedSteps; i++) {
    const bearing = (i * 360) / resolvedSteps;
    ring.push(destinationPoint(center, radiusMeters, bearing));
  }
  ring.push(ring[0] as Coordinate);

  return {
    type: "Feature",
    properties,
    geometry: {
      type: "Polygon",
      coordinates: [ring],
    },
  };
}

function eachCoordinate(geometry: Geometry, visit: (coord: Coordinate) => void): void {
  switch (geometry.type) {
    case "Point":
      visit(geometry.coordinates as Coordinate);
      return;
    case "MultiPoint":
    case "LineString":
      geometry.coordinates.forEach((c) => visit(c as Coordinate));
      return;
    case "MultiLineString":
    case "Polygon":
      geometry.coordinates.forEach((ring) => ring.forEach((c) => visit(c as Coordinate)));
      return;
    case "MultiPolygon":
      geometry.coordinates.forEach((poly) => poly.forEach((ring) => ring.forEach((c) => visit(c as Coordinate))));
      return;
    case "GeometryCollection":
      geometry.geometries.forEach((g) => eachCoordinate(g, visit));
      return;
  }
}

function eachFeature(input: GeoJSONInput, visit: (feature: Feature) => void): void {
  const data = typeof input === "string" ? (JSON.parse(input) as GeoJSONInput) : input;
  if (typeof data === "string") return;

  if (data.type === "FeatureCollection") {
    (data as FeatureCollection).features.forEach(visit);
  } else if (data.type === "Feature") {
    visit(data as Feature);
  } else {
    visit({ type: "Feature", properties: {}, geometry: data as Geometry });
  }
}

/** Bounding box of arbitrary GeoJSON input, as `[west, south, east, north]`. */
export function bboxOf(input: GeoJSONInput): Bounds {
  let west = Infinity;
  let south = Infinity;
  let east = -Infinity;
  let north = -Infinity;

  eachFeature(input, (feature) => {
    eachCoordinate(feature.geometry, ([lon, lat]) => {
      if (lon < west) west = lon;
      if (lon > east) east = lon;
      if (lat < south) south = lat;
      if (lat > north) north = lat;
    });
  });

  if (!Number.isFinite(west)) {
    throw new Error("bboxOf: input contains no coordinates");
  }

  return [west, south, east, north];
}

/** Alias kept for readability at call sites that think in "bounds", not "bbox". */
export const boundsOf = bboxOf;

/**
 * Computes a numeric property on every feature in a collection, returning a
 * new collection (features are shallow-cloned; original is not mutated).
 * This is the documented alternative to a runtime value-accessor callback
 * for `MapChoropleth` (see plan §7.6) — native style evaluation can't call
 * back into JS per-frame, so the value must be precomputed once.
 */
export function precomputeValues<P extends GeoJsonProperties = GeoJsonProperties>(
  data: FeatureCollection<Geometry, P>,
  compute: (feature: Feature<Geometry, P>) => number | null,
  property: string,
): FeatureCollection {
  return {
    type: "FeatureCollection",
    features: data.features.map((feature) => ({
      ...feature,
      properties: {
        ...feature.properties,
        [property]: compute(feature),
      },
    })),
  };
}

/** Built-in sequential and diverging color ramps for choropleths/heatmaps. */
export const SEQUENTIAL_RAMPS: Record<string, Array<string>> = {
  blues: ["#f7fbff", "#c6dbef", "#6baed6", "#2171b5", "#08306b"],
  greens: ["#f7fcf5", "#c7e9c0", "#74c476", "#238b45", "#00441b"],
  oranges: ["#fff5eb", "#fdd0a2", "#fd8d3c", "#d94801", "#7f2704"],
  reds: ["#fff5f0", "#fcbba1", "#fb6a4a", "#cb181d", "#67000d"],
  purples: ["#fcfbfd", "#dadaeb", "#9e9ac8", "#6a51a3", "#3f007d"],
};

export const DIVERGING_RAMPS: Record<string, Array<string>> = {
  redBlue: ["#67001f", "#d6604d", "#f7f7f7", "#4393c3", "#053061"],
  redGreen: ["#a50026", "#f46d43", "#ffffbf", "#66bd63", "#006837"],
};

export function hexToRgba(hex: string, alpha = 1): string {
  const normalized = hex.replace("#", "");
  const bigint = parseInt(
    normalized.length === 3
      ? normalized
          .split("")
          .map((c) => c + c)
          .join("")
      : normalized,
    16,
  );
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

/** Evenly spreads `count` colors across a ramp via linear interpolation between stops. */
export function sampleRamp(ramp: Array<string>, count: number): Array<string> {
  if (count <= 1) return [ramp[0] as string];
  if (ramp.length === count) return [...ramp];

  const result: Array<string> = [];
  for (let i = 0; i < count; i++) {
    const t = i / (count - 1);
    const scaledIndex = t * (ramp.length - 1);
    const lowerIndex = Math.floor(scaledIndex);
    const upperIndex = Math.min(ramp.length - 1, lowerIndex + 1);
    const localT = scaledIndex - lowerIndex;
    result.push(lerpColor(ramp[lowerIndex] as string, ramp[upperIndex] as string, localT));
  }
  return result;
}

function lerpColor(a: string, b: string, t: number): string {
  const parse = (hex: string) => {
    const n = hex.replace("#", "");
    const full = n.length === 3
      ? n.split("").map((c) => c + c).join("")
      : n;
    const int = parseInt(full, 16);
    return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
  };
  const [r1, g1, b1] = parse(a);
  const [r2, g2, b2] = parse(b);
  const round = (v: number) => Math.round(v).toString(16).padStart(2, "0");
  const r = round((r1 as number) + ((r2 as number) - (r1 as number)) * t);
  const g = round((g1 as number) + ((g2 as number) - (g1 as number)) * t);
  const bl = round((b1 as number) + ((b2 as number) - (b1 as number)) * t);
  return `#${r}${g}${bl}`;
}

import type { Feature, FeatureCollection, Geometry } from "geojson";
import type { Expression, MapLegendData } from "./types";
import { sampleRamp } from "./colors";

export type ChoroplethScale =
  | { type: "quantize"; steps?: number; colors?: Array<string>; domain?: [number, number] }
  | { type: "quantile"; steps?: number; colors?: Array<string> }
  | { type: "threshold"; breaks: Array<number>; colors: Array<string> }
  | { type: "linear"; colors: Array<string>; domain?: [number, number] };

const DEFAULT_COLORS = ["#eff3ff", "#bdd7e7", "#6baed6", "#3182bd", "#08519c"];

function extractValues(data: FeatureCollection, property: string): Array<number> {
  const values: Array<number> = [];
  for (const feature of data.features as Array<Feature<Geometry>>) {
    const raw = feature.properties?.[property];
    if (typeof raw === "number" && Number.isFinite(raw)) values.push(raw);
  }
  return values;
}

function domainOf(values: Array<number>): [number, number] {
  if (values.length === 0) return [0, 1];
  let min = Infinity;
  let max = -Infinity;
  for (const v of values) {
    if (v < min) min = v;
    if (v > max) max = v;
  }
  return [min, max];
}

function quantiles(sorted: Array<number>, steps: number): Array<number> {
  const breaks: Array<number> = [];
  for (let i = 1; i < steps; i++) {
    const pos = (i / steps) * (sorted.length - 1);
    const lower = Math.floor(pos);
    const upper = Math.ceil(pos);
    const weight = pos - lower;
    const value =
      lower === upper
        ? (sorted[lower] as number)
        : (sorted[lower] as number) * (1 - weight) + (sorted[upper] as number) * weight;
    breaks.push(value);
  }
  return breaks;
}

export interface ComputedScale {
  /** Ascending break points, excluding the domain min/max. */
  breaks: Array<number>;
  colors: Array<string>;
  domain: [number, number];
}

/** Computes breaks + colors for a scale, given the data it will be applied to. */
export function computeScale(scale: ChoroplethScale, data: FeatureCollection, property: string): ComputedScale {
  switch (scale.type) {
    case "threshold":
      return { breaks: scale.breaks, colors: scale.colors, domain: domainOf(extractValues(data, property)) };

    case "linear": {
      const domain = scale.domain ?? domainOf(extractValues(data, property));
      return { breaks: [], colors: scale.colors, domain };
    }

    case "quantize": {
      const steps = scale.steps ?? 5;
      const domain = scale.domain ?? domainOf(extractValues(data, property));
      const [min, max] = domain;
      const span = max - min;
      const breaks: Array<number> = [];
      for (let i = 1; i < steps; i++) breaks.push(min + (span * i) / steps);
      return { breaks, colors: scale.colors ?? sampleRamp(DEFAULT_COLORS, steps), domain };
    }

    case "quantile": {
      const steps = scale.steps ?? 5;
      const sorted = extractValues(data, property).slice().sort((a, b) => a - b);
      const breaks = quantiles(sorted, steps);
      return {
        breaks,
        colors: scale.colors ?? sampleRamp(DEFAULT_COLORS, steps),
        domain: domainOf(sorted),
      };
    }
  }
}

/**
 * Compiles a computed scale into a style-spec `["step", ...]` expression.
 * Used for quantize/quantile/threshold scales, which are inherently
 * discrete.
 */
export function buildStepExpression(
  property: string,
  computed: ComputedScale,
  missingColor = "rgba(0,0,0,0)",
): Expression {
  const expression: Expression = [
    "case",
    ["!", ["has", property]],
    missingColor,
    [
      "step",
      ["get", property],
      computed.colors[0],
    ],
  ];
  const stepArgs = expression[3] as Expression;
  computed.breaks.forEach((breakpoint, i) => {
    stepArgs.push(breakpoint, computed.colors[i + 1]);
  });
  return expression;
}

/** Compiles a continuous (linear) scale into an `["interpolate", ["linear"], ...]` expression. */
export function buildInterpolateExpression(
  property: string,
  colors: Array<string>,
  domain: [number, number],
  missingColor = "rgba(0,0,0,0)",
): Expression {
  const [min, max] = domain;
  const span = max - min || 1;
  const stops: Expression = ["interpolate", ["linear"], ["get", property]];
  colors.forEach((color, i) => {
    const t = i / (colors.length - 1 || 1);
    stops.push(min + span * t, color);
  });
  return ["case", ["!", ["has", property]], missingColor, stops];
}

export function buildChoroplethLegend(
  scale: ChoroplethScale,
  computed: ComputedScale,
  options?: { unit?: string },
): MapLegendData {
  if (scale.type === "linear") {
    const [min, max] = computed.domain;
    const span = max - min || 1;
    return {
      type: "gradient",
      domain: computed.domain,
      unit: options?.unit,
      stops: computed.colors.map((color, i) => ({
        at: min + span * (i / (computed.colors.length - 1 || 1)),
        color,
      })),
    };
  }

  const edges = [computed.domain[0], ...computed.breaks, computed.domain[1]];
  return {
    type: "steps",
    unit: options?.unit,
    items: computed.colors.map((color, i) => ({
      color,
      from: edges[i],
      to: edges[i + 1],
      label: `${formatNumber(edges[i] as number)}–${formatNumber(edges[i + 1] as number)}`,
    })),
  };
}

export function buildHeatmapLegend(
  colors: Array<string>,
  domain: [number, number],
  options?: { unit?: string },
): MapLegendData {
  const [min, max] = domain;
  const span = max - min || 1;
  return {
    type: "gradient",
    domain,
    unit: options?.unit,
    stops: colors.map((color, i) => ({
      at: min + span * (i / (colors.length - 1 || 1)),
      color,
    })),
  };
}

export function buildCategoricalLegend(
  entries: Array<{ label: string; color: string; value?: string | number }>,
): MapLegendData {
  return { type: "categorical", items: entries };
}

function formatNumber(value: number): string {
  return Math.abs(value) >= 1000 ? value.toFixed(0) : Number(value.toFixed(2)).toString();
}

import type { MapRenderer } from "./types";

export type MapProviderId = "maptiler" | "carto" | "custom" | "mapbox";

export interface MapStyleDefinition {
  id: string;
  label: string;
  /** Resolved lazily so the API key is read at call time, not module init. */
  url: (ctx: { apiKey?: string }) => string;
  colorScheme?: "light" | "dark";
}

export interface MapProviderDefinition {
  id: MapProviderId;
  renderer: MapRenderer;
  label: string;
  /** Public runtime env var name. null = no key required (CARTO). */
  envKey: string | null;
  /** Extra secret needed at *build* time (Mapbox Android downloads token). */
  buildEnvKey?: string;
  requiresKey: boolean;
  attribution: string;
  docsUrl: string;
  styles: Record<string, MapStyleDefinition>;
  defaultStyle: { light: string; dark: string };
}

